import Foundation
import Yams

/// One note of `database/Projets`: its properties, then the three parts Paul and his tools write (Notes,
/// Actions, Journal). The parts generated by scripts are left out.
public enum NoteParser {
    public static func parse(_ raw: String, name: String, relativePath: String? = nil) -> (ImportedProject, warning: String?) {
        var project = ImportedProject(name: name, relativePath: relativePath ?? "database/Projets/\(name).md")
        // Windows line endings and a byte-order mark would hide everything (review, minor 5).
        var text = raw.replacingOccurrences(of: "\r\n", with: "\n").replacingOccurrences(of: "\r", with: "\n")
        if text.hasPrefix("\u{FEFF}") { text.removeFirst() }
        let (frontmatter, body) = split(text)
        var warning: String?
        if let frontmatter {
            do {
                let properties = (try Yams.load(yaml: frontmatter, VaultDates.resolver) as? [String: Any]) ?? [:]
                apply(properties, to: &project)
            } catch {
                warning = "« \(name) » : propriétés illisibles, la note est importée sans elles."
            }
        }
        let sections = sections(body)
        project.notes = notes(sections)
        project.actions = sections.filter { $0.title == "Actions" }.flatMap { actions($0.text) }
        project.journal = sections.filter { $0.title == "Journal" }.flatMap { journal($0.text) }
        return (project, warning)
    }

    /// The parts the page generator writes above « Notes ».
    static let generated: Set<String> = ["Réunions", "Échanges récents", "Sites de référence"]

    /// From the first « Notes » on, everything is Paul's: the Notes parts, and every other part with its
    /// title, except Actions and Journal (review, Important 4: a Notion page pasted there keeps its parts).
    static func notes(_ sections: [Section]) -> String {
        let start = sections.firstIndex { $0.title == "Notes" } ?? 0
        return sections[start...]
            .filter { $0.title != "Actions" && $0.title != "Journal" && !generated.contains($0.title) }
            .map { section -> String in
                let text = section.text.trimmingCharacters(in: .whitespacesAndNewlines)
                if section.title == "Notes" { return text }
                return text.isEmpty ? "## \(section.title)" : "## \(section.title)\n\(text)"
            }
            .map(WikiLinks.plain)
            .filter { !$0.isEmpty }
            .joined(separator: "\n\n")
    }

    /// The YAML between the first two `---`, and the rest.
    static func split(_ text: String) -> (String?, String) {
        let lines = text.components(separatedBy: "\n")
        guard lines.first?.trimmingCharacters(in: .whitespaces) == "---",
              let end = lines.dropFirst().firstIndex(where: { $0.trimmingCharacters(in: .whitespaces) == "---" })
        else { return (nil, text) }
        return (lines[1..<end].joined(separator: "\n"), lines[(end + 1)...].joined(separator: "\n"))
    }

    static func apply(_ properties: [String: Any], to project: inout ImportedProject) {
        // An empty property (`todo:`) is NSNull, an unquoted `[[X]]` a list in a list (review, Important 1).
        func text(_ key: String) -> String? {
            guard let string = flatten(properties[key]).first else { return nil }
            let plain = WikiLinks.plain(string).trimmingCharacters(in: .whitespacesAndNewlines)
            return plain.isEmpty ? nil : plain
        }
        project.status = text("statut")
        project.client = text("client")
        project.todo = text("todo")
        project.icon = text("icone")
        project.color = text("couleur")
        project.codeFolder = text("dossier")
        project.github = text("github")
        project.notion = text("notion")
        project.dueDate = VaultDates.date(properties["echeance"])
        project.createdOn = VaultDates.date(properties["date"])
        project.lastActivity = VaultDates.date(properties["derniere_activite"])
        project.contacts = flatten(properties["contacts"]).map(WikiLinks.plain).filter { !$0.isEmpty }
    }

    /// A list, a list of lists (`[[X]]` unquoted in YAML), or one value.
    static func flatten(_ value: Any?) -> [String] {
        switch value {
        case let list as [Any]:
            // `[[X]]` unquoted: YAML reads a list holding a list; it was a link.
            list.flatMap { item in (item as? [Any]).map { inner in flatten(inner).map { "[[\($0)]]" } } ?? flatten(item) }
        case let string as String: [string]
        case nil, is NSNull: []
        case let other?: ["\(other)"]
        }
    }

    struct Section {
        let title: String
        var text: String
    }

    /// The parts of the body, cut at `## ` titles outside code blocks; what comes before the first title
    /// (the generated callout) is dropped.
    static func sections(_ body: String) -> [Section] {
        var sections: [Section] = []
        var inFence = false
        for line in body.components(separatedBy: "\n") {
            if line.trimmingCharacters(in: .whitespaces).hasPrefix("```") { inFence.toggle() }
            if !inFence, line.hasPrefix("## ") {
                sections.append(Section(title: String(line.dropFirst(3)).trimmingCharacters(in: .whitespaces), text: ""))
            } else if !sections.isEmpty {
                sections[sections.count - 1].text += line + "\n"
            }
        }
        return sections
    }

    /// `- [ ] texte · 2026-11-06`, `- [x] …`.
    static func actions(_ text: String) -> [ImportedAction] {
        text.components(separatedBy: "\n").compactMap { line in
            guard let match = line.firstMatch(of: #/^\s*(?:[-*+]|\d+[.)])\s+\[(.)\]\s+(.+)$/#) else { return nil }
            var content = String(match.output.2).trimmingCharacters(in: .whitespaces)
            var addedOn: Date?
            if let dated = content.firstMatch(of: #/^(.*?)\s*·\s*(\d{4}-\d{2}-\d{2})\s*$/#) {
                content = String(dated.output.1)
                addedOn = VaultDates.date(String(dated.output.2))
            }
            return ImportedAction(text: WikiLinks.plain(content), done: match.output.1 != " ", addedOn: addedOn)
        }
    }

    /// `### 2026-11-06 — titre`, then its lines.
    static func journal(_ text: String) -> [ImportedJournalEntry] {
        var entries: [ImportedJournalEntry] = []
        var lines: [String] = []
        func close() {
            guard !entries.isEmpty else { return }
            entries[entries.count - 1].body = WikiLinks.plain(lines.joined(separator: "\n").trimmingCharacters(in: .whitespacesAndNewlines))
            lines = []
        }
        for line in text.components(separatedBy: "\n") {
            if let heading = line.firstMatch(of: #/^### (\d{4}-\d{2}-\d{2})\s*[—–-]?\s*(.*)$/#), let date = VaultDates.date(String(heading.output.1)) {
                close()
                entries.append(ImportedJournalEntry(date: date, title: WikiLinks.plain(String(heading.output.2)), body: ""))
            } else if !entries.isEmpty {
                lines.append(line)
            }
        }
        close()
        return entries
    }
}
